  function routeFromHash() { const route = location.hash.slice(1).split('/')[0].split('?')[0]; return ['home', 'catalog', 'booklet', 'requests', 'request-category', 'request-create', 'request-response', 'quotes', 'login', 'register', 'inquiry', 'buyer', 'batch-inquiry', 'supplier', 'services', 'farmer-register', 'calendar', 'feedback', 'service-request'].includes(route) ? route : 'home'; }
